924: function TaxSandbox() {
925:   const [income, setIncome] = useState("1200000");
926:   const [deductions, setDeductions] = useState([
927:     { id: '80c', name: '80C Investments (PPF, ELSS)', max: 150000, active: false, desc: 'Max limit ₹1.5L' },
928:     { id: '80ccd', name: 'NPS (Pension System)', max: 50000, active: false, desc: 'Extra ₹50k under 80CCD(1B)' },
929:     { id: '80d', name: 'Health Insurance', max: 75000, active: false, desc: 'Up to ₹75k limit' },
930:     { id: '24b', name: 'Home Loan Interest', max: 200000, active: false, desc: 'Up to ₹2L limit' }
931:   ]);
932:   const [animatedTakehome, setAnimatedTakehome] = useState(0);
933:   const animTakehomeRef = useRef(0);
934: 
935:   const numGross = Math.max(0, parseInt(income.replace(/[^0-9]/g, "")) || 0);
936:   
937:   const calcTax = (taxable: number, regime: "new" | "old") => {
938:     if (regime === 'new') {
939:       let tax = 0;
940:       // Budget 2024 New Regime Slabs:
941:       // 0 - 3L: Nil
942:       // 3L - 7L: 5% (max ₹20,000)
943:       // 7L - 10L: 10% (max ₹30,000)
944:       // 10L - 12L: 15% (max ₹30,000)
945:       // 12L - 15L: 20% (max ₹60,000)
946:       // Above 15L: 30%
947:       if (taxable > 300000) {
948:         tax += Math.min(taxable - 300000, 400000) * 0.05;
949:       }
950:       if (taxable > 700000) {
951:         tax += Math.min(taxable - 700000, 300000) * 0.10;
952:       }
953:       if (taxable > 1000000) {
954:         tax += Math.min(taxable - 1000000, 200000) * 0.15;
955:       }
956:       if (taxable > 1200000) {
957:         tax += Math.min(taxable - 1200000, 300000) * 0.20;
958:       }
959:       if (taxable > 1500000) {
960:         tax += (taxable - 1500000) * 0.30;
961:       }
962: 
963:       // Section 87A Full Rebate & Marginal Relief Proviso
964:       if (taxable <= 700000) {
965:         tax = 0; // Section 87A rebate
966:       } else {
967:         // Section 87A marginal relief proviso: tax liability capped at income exceeding ₹7,00,000
968:         const excessIncome = taxable - 700000;
969:         if (tax > excessIncome) {
970:           tax = excessIncome;
971:         }
972:       }
973:       return tax;
974:     } else {
975:       let tax = 0;
976:       if (taxable > 250000) {
977:         tax += Math.min(taxable - 250000, 250000) * 0.05;
978:       }
979:       if (taxable > 500000) {
980:         tax += Math.min(taxable - 500000, 500000) * 0.20;
981:       }
982:       if (taxable > 1000000) {
983:         tax += (taxable - 1000000) * 0.30;
984:       }
985:       if (taxable <= 500000) {
986:         tax = 0; // Section 87A rebate under Old Regime
987:       }
988:       return tax;
989:     }
990:   };
991: 
992:   // Statutory Standard Deductions: ₹75,000 for New Regime (Budget 2024 / FY 2024-25), ₹50,000 for Old Regime
993:   const stdDed = 75000;
994:   const stdDedOld = 50000;
995:   const customDed = deductions.filter(d => d.active).reduce((sum, d) => sum + d.max, 0);
996:   
997:   const taxableNew = Math.max(0, numGross - stdDed);
998:   const taxableOld = Math.max(0, numGross - stdDedOld - customDed);
999: 
1000:   const baseTaxNew = calcTax(taxableNew, 'new');
1001:   const baseTaxOld = calcTax(taxableOld, 'old');
1002: 
1003:   // 4% Health & Education cess
1004:   const taxNew = Math.round(baseTaxNew * 1.04);
1005:   const taxOld = Math.round(baseTaxOld * 1.04);
1006:   
1007:   const isOldBetter = customDed > 0 || taxOld < taxNew;
1008:   const finalTax = isOldBetter ? taxOld : taxNew;
1009:   const takeHome = Math.max(0, numGross - finalTax);
1010: 
1011:   useEffect(() => {
1012:     const start = animTakehomeRef.current;
1013:     const end = takeHome;
1014:     if (start === end) return;
1015:     const duration = 400;
1016:     let startTimestamp: number | null = null;
1017:     let frameId: number;
1018:     const step = (timestamp: number) => {
1019:       if (!startTimestamp) startTimestamp = timestamp;
1020:       const progress = Math.min((timestamp - startTimestamp) / duration, 1);
1021:       const easeOut = 1 - Math.pow(1 - progress, 5);
1022:       const current = start + (end - start) * easeOut;
1023:       animTakehomeRef.current = current;
1024:       setAnimatedTakehome(current);
1025:       if (progress < 1) {
1026:         frameId = window.requestAnimationFrame(step);
1027:       }
1028:     };
1029:     frameId = window.requestAnimationFrame(step);
1030:     return () => window.cancelAnimationFrame(frameId);
1031:   }, [takeHome]);
1032: 
1033:   const taxPct = numGross > 0 ? (finalTax / numGross) * 100 : 0;
1034:   const takePct = numGross > 0 ? 100 - taxPct : 0;
1035: 
1036:   const toggleDed = (index: number) => {
1037:     const newDed = [...deductions];
1038:     newDed[index].active = !newDed[index].active;
1039:     setDeductions(newDed);
1040:   };
1041: 
1042:   return (
1043:     <div className="glass-card p-6 md:p-8 lg:p-12 overflow-hidden relative">
1044:       <div className="absolute top-0 right-0 w-64 h-64 bg-emerald-500/10 blur-[80px] pointer-events-none"></div>
1045:       
1046:       <div className="grid grid-cols-1 lg:grid-cols-12 gap-10 relative z-10">
1047:         <div className="lg:col-span-7 space-y-8">
1048:           <div>
