1053:               <span className="text-4xl md:text-5xl text-white/60 mr-2 tabular-nums">₹</span>
1054:               <input 
1055:                 id="tax-income-input"
1056:                 name="taxIncome"
1057:                 aria-label="Annual Gross Income"
1058:                 type="text" 
1059:                 inputMode="numeric"
1060:                 value={income}
1061:                 onChange={(e) => {
1062:                   const val = Math.max(0, parseInt(e.target.value.replace(/[^0-9]/g, "")) || 0);
1063:                   setIncome(val === 0 ? "" : val.toLocaleString('en-IN'));
1064:                 }}
1065:                 className="w-full bg-transparent border-none text-4xl md:text-5xl font-bold tabular-nums text-white outline-none"
1066:               />
1067:             </div>
1068:           </div>
1069: 
1070:           <div className="pt-4">
1071:             <div className="flex justify-between items-end mb-6">
1072:               <div>
1073:                 <h3 className="text-lg font-semibold">Tax Saving Strategies</h3>
1074:                 <p className="text-xs text-white/60 mt-1">Toggle Chapter VI-A investments to simulate Old vs New Regime take-home pay.</p>
1075:               </div>
1076:             </div>
1077:             <div className="space-y-2">
1078:               {deductions.map((d, i) => (
1079:                 <button
1080:                   key={d.id}
1081:                   type="button"
1082:                   role="switch"
1083:                   aria-checked={d.active}
1084:                   tabIndex={0}
1085:                   onClick={() => toggleDed(i)}
1086:                   className="w-full text-left flex items-center justify-between p-4 rounded-xl bg-white/[0.02] border border-white/5 hover:border-white/10 cursor-pointer transition-colors group focus:outline-none focus-visible:ring-2 focus-visible:ring-emerald-400"
1087:                 >
1088:                   <div>
1089:                     <div className="text-sm font-medium text-white group-hover:text-emerald-400 transition-colors">{d.name}</div>
1090:                     <div className="text-xs text-white/60 font-mono mt-0.5">{d.desc}</div>
1091:                   </div>
1092:                   <div className={"w-12 h-6 rounded-full relative transition-colors duration-300 shrink-0 ml-4 " + (d.active ? "bg-emerald-500" : "bg-white/10")}>
1093:                     <div className={"absolute top-1 left-1 w-4 h-4 bg-white rounded-full transition-transform duration-300 shadow-md " + (d.active ? "translate-x-6" : "translate-x-0")}></div>
1094:                   </div>
1095:                 </button>
1096:               ))}
1097:             </div>
1098:           </div>
1099:         </div>
1100: 
1101:         <div aria-live="polite" aria-atomic="true" className="lg:col-span-5 flex flex-col justify-center border-t lg:border-t-0 lg:border-l border-white/10 pt-8 lg:pt-0 lg:pl-10">
1102:           <p className="text-white/50 text-sm mb-1">True Take-Home Pay</p>
