1150: function InvoiceStrategist() {
1151:   const [target, setTarget] = useState("100000");
1152:   const [gstRate, setGstRate] = useState(18);
1153:   const [hasTds, setHasTds] = useState(false);
1154:   const [isReverse, setIsReverse] = useState(true);
1155:   const [isInterState, setIsInterState] = useState(false);
1156: 
1157:   // Sanitize numerical inputs to prevent NaN or negative values
1158:   const numInput = Math.max(0, parseFloat(target.replace(/[^0-9.]/g, "")) || 0);
1159:   const rateDec = gstRate / 100;
1160: 
1161:   let base = 0;
1162:   let gstAmt = 0;
1163:   let totalInvoice = 0;
1164: 
1165:   if (isReverse) {
1166:     // Reverse Invoicing: Target amount is inclusive of GST
1167:     totalInvoice = numInput;
1168:     base = rateDec > 0 ? Math.round((totalInvoice / (1 + rateDec)) * 100) / 100 : totalInvoice;
1169:     gstAmt = Math.round((totalInvoice - base) * 100) / 100;
1170:   } else {
1171:     // Forward Invoicing: Input amount is base consultation fee
1172:     base = numInput;
1173:     gstAmt = Math.round((base * rateDec) * 100) / 100;
1174:     totalInvoice = Math.round((base + gstAmt) * 100) / 100;
1175:   }
1176: 
1177:   const tdsAmt = hasTds ? Math.round(base * 0.10 * 100) / 100 : 0;
1178:   const clientPays = Math.round((totalInvoice - tdsAmt) * 100) / 100;
1179:   const netCash = Math.round((clientPays - gstAmt) * 100) / 100;
1180: 
1181:   // Tax Breakdown: Intra-state (CGST + SGST) vs Inter-state (IGST)
1182:   const cgst = isInterState ? 0 : Math.round((gstAmt / 2) * 100) / 100;
1183:   const sgst = isInterState ? 0 : Math.round((gstAmt - cgst) * 100) / 100;
1184:   const igst = isInterState ? gstAmt : 0;
1185: 
1186:   // Compliance Flags
1187:   const eWayBillRequired = totalInvoice > 50000;
1188: 
1189:   return (
